with valid as (select id, order_id, quantity, unit_price, greatest(quantity, unit_price) as greatest_quantity_unit_price from order_items where product_id is not null), with_windows as (select *, ntile(10) over (partition by order_id order by unit_price desc, id) as unit_price_bucket, ntile(10) over w_part as greatest_quantity_unit_price_bucket, sum(quantity) over w_part_2 as cumulative_quantity from valid where unit_price <= 170 window w_part as (order by greatest_quantity_unit_price desc, id), w_part_2 as (order by quantity, id rows between unbounded preceding and current row)), metrics as (select id, quantity, unit_price, greatest_quantity_unit_price, cumulative_quantity, avg(quantity) over (order by unit_price, id rows between 2 preceding and 1 preceding) as quantity_avg_2_prior, sum(quantity) over (partition by order_id) as order_id_sum_quantity from with_windows), with_windows_order_items as (select *, sum(order_id_sum_quantity) over (order by cumulative_quantity, id rows between unbounded preceding and current row) as running_order_id_sum_quantity, ntile(4) over w_running as greatest_quantity_unit_price_bucket, cume_dist() over w_part as unit_price_cume_dist, sum(order_id_sum_quantity) over w_ordered as cumulative_order_id_sum_quantity from metrics window w_running as (order by greatest_quantity_unit_price, id), w_part as (order by unit_price desc), w_ordered as (order by quantity_avg_2_prior, id rows between unbounded preceding and current row)), base as (select *, ceil(greatest_quantity_unit_price) as greatest_quantity_unit_price_whole from with_windows_order_items where greatest_quantity_unit_price >= 51), filtered as (select *, cast(order_id_sum_quantity as string) as order_id_sum_quantity_num from base where quantity_avg_2_prior < 5), totals as (select case when quantity_avg_2_prior >= 9 then 'LARGE' else 'SMALL' end as quantity_avg_2_prior_tier, case when greatest_quantity_unit_price_bucket >= 8 then 'LARGE' else 'SMALL' end as greatest_quantity_unit_price_bucket_tier, case when cumulative_order_id_sum_quantity >= 217 then 'LARGE' else 'SMALL' end as cumulative_order_id_sum_quantity_tier, approx_percentile(running_order_id_sum_quantity, 0.95) as running_order_id_sum_quantity_p95, count(distinct id) as distinct_ids, count(distinct id) as distinct_ids_2 from filtered group by case when quantity_avg_2_prior >= 9 then 'LARGE' else 'SMALL' end, case when greatest_quantity_unit_price_bucket >= 8 then 'LARGE' else 'SMALL' end, case when cumulative_order_id_sum_quantity >= 217 then 'LARGE' else 'SMALL' end) select quantity_avg_2_prior_tier, greatest_quantity_unit_price_bucket_tier, cumulative_order_id_sum_quantity_tier, distinct_ids, distinct_ids_2 from totals order by distinct_ids_2 desc nulls last;
